VID.narration = {"look":{"bar":false},"scenes":[{"dur":9.288,"caps":[[0.5,7.87,"Algorithms, phase three. Optimisation. This is how factories and AI find the best plan."]],"warp":[[0,0],[0.5,0.9],[9.288,4]]},{"dur":28.352,"caps":[[0.5,5.71,"Choose x of product X and y of product Y."],[5.96,10.85,"Each rule cuts the plane in half."],[11.1,14.87,"The overlap is the feasible region."],[15.12,20.73,"Plug a plan into every rule. Pass all: legal."],[20.98,27.63,"Break even one rule and it is not allowed."]],"warp":[[0,0],[0.5,0.4],[5.96,2.2],[11.1,5.4],[15.12,7.4],[20.98,10.6],[28.352,17]]},{"dur":19.992,"caps":[[0.5,5.55,"Each plan earns a score: z = 3x + 2y."],[5.8,9.01,"Every point on this line scores the same."],[9.26,13.59,"Slide the profit line outwards until it leaves."],[13.84,17.93,"It leaves at a corner, so check only the corners."]],"warp":[[0,0],[0.5,0.4],[5.8,2.6],[9.26,4.4],[13.84,7.4],[19.992,12]]},{"dur":30,"caps":[[0.5,4.59,"Start at a corner. Which direction gains most?"],[4.84,11.17,"Walk until the nearest rule blocks the way."],[11.42,15.27,"Repeat. s = what a rule has left over."],[15.52,22.81,"Leftovers cost profit, so only y gains."],[23.06,28.43,"No direction gains: the corner is optimal."]],"warp":[[0,0],[0.5,0.4],[4.84,3.6],[11.42,6.6],[15.52,9],[23.06,11.8],[30,16]]},{"dur":25.008,"caps":[[0.5,5.15,"New problem: one number. Find the lowest point."],[5.4,10.53,"Falling, then rising: a minimum is trapped."],[10.78,15.51,"Bisection: test the middle. Still falling?"],[15.76,18.89,"Keep the half where the slope flips."],[19.14,23.55,"Each step halves the bracket."]],"warp":[[0,0],[0.5,0.4],[5.4,2.7],[10.78,4.6],[15.76,7.2],[19.14,10],[25.008,13]]},{"dur":23.313,"caps":[[0.5,5.39,"Golden section: no slope, three heights trap it."],[5.64,10.53,"One probe a step: the lowest stays in the middle."],[10.78,15.99,"Old probes are reused, so each cut costs one test."],[16.24,21.69,"Each step keeps 0.618 of the bracket."]],"warp":[[0,0],[0.5,0.4],[5.64,3.4],[10.78,5.3],[16.24,7.3],[23.313,13]]},{"dur":21.687,"caps":[[0.5,4.59,"Same curve: fit a parabola through three points."],[4.84,7.97,"Jump to the bottom of the parabola."],[8.22,11.43,"Repeat: the bracket collapses fast."],[11.68,16.25,"Jump not shrinking? Take a golden step instead."],[16.5,21.15,"Same 7 tests, a bracket 5 times tighter."]],"warp":[[0,0],[0.5,0.4],[4.84,2.5],[8.22,5.8],[11.68,8.6],[16.5,12.4],[21.687,15]]},{"dur":25.008,"caps":[[0.5,4.43,"Two numbers, no slopes: keep a triangle."],[4.68,8.37,"Flip the worst corner through the middle."],[8.62,11.75,"A great flip? Stretch even further."],[12,15.37,"Stretched too far? Keep the plain flip."],[15.62,19.55,"Flip overshoots? Pull the corner in instead."],[19.8,24.37,"If every try fails: shrink towards the best."]],"warp":[[0,0],[0.5,0.4],[4.68,2.6],[8.62,4.6],[12,7],[15.62,9.9],[19.8,13],[25.008,15]]},{"dur":21.757,"caps":[[0.5,4.59,"Real problems have curved valleys, not bowls."],[4.84,8.13,"Moves work? The triangle stretches."],[8.38,11.99,"More good moves: it stretches along the valley."],[12.24,15.69,"Near the end it squeezes to a tiny triangle."],[15.94,20.91,"No derivatives needed, just comparisons."]],"warp":[[0,0],[0.5,0.4],[4.84,3],[8.38,5.6],[12.24,8.8],[15.94,11.5],[21.757,14]]},{"dur":13.236,"caps":[],"warp":[[0,0],[0.5,0.9],[4.84,2],[7.98,3.1],[13.236,9]]}]};
